edits.new:
sub('Rumusan Masalah');
const rq = ['Bagaimana kualitas dataset ditinjau dari kelengkapan, integritas, dan konsistensi?', 'Bagaimana karakteristik statistik, sebaran, dan nilai ekstrem variabel numerik?', 'Bagaimana hubungan antarvariabel numerik dan antarvariabel kategorikal?'];
if (sheet.trends.length || sheet.groupBars.length) { rq.push('Bagaimana pola tren waktu dan perbedaan antarkelompok?'); }
if (stock) { rq.push('Bagaimana kondisi persediaan, konsentrasi nilai, dan kebutuhan pengadaan barang?'); }
if (dt) { rq.push('Seberapa baik model Decision Tree C4.5 mengklasifikasikan atribut target?'); }
p('Berdasarkan latar belakang tersebut, rumusan masalah penelitian ini adalah sebagai berikut.');
ul(rq);

sub('Tujuan Penelitian');
p('Tujuan penelitian ini adalah menjawab seluruh rumusan masalah di atas, yaitu:');
const tujuanPoin: string[] = [];
tujuanPoin.push(`Menganalisis kualitas dan integritas data (skor saat ini ${hl.qualityScore}%) serta menentukan penanganan yang tepat terhadap ${hl.missingCells > 0 ? 'sel kosong' : 'struktur data'} dan ${hl.outlierColsCount > 0 ? 'nilai pencilan' : 'sebaran data'}.`);
if (pairs.length) { tujuanPoin.push('Memetakan hubungan dan korelasi antarvariabel untuk menentukan derajat keterikatan fitur serta menghindari risiko multikolinearitas dalam pemodelan.'); }
if (tr0) { tujuanPoin.push(`Mengidentifikasi pola temporal dan dinamika perubahan data antarperiode pada variabel "${tr0.num}" untuk kebutuhan proyeksi atau perencanaan berkala.`); }
if (stock) { tujuanPoin.push('Menentukan prioritas pengelolaan aset persediaan melalui klasifikasi ABC serta memetakan item yang kritis maupun overstock.'); }
if (dt) { tujuanPoin.push('Mengevaluasi kinerja model klasifikasi C4.5 dalam menghasilkan aturan keputusan yang akurat dan mudah diinterpretasikan.'); }
tujuanPoin.push('Merumuskan rekomendasi tindak lanjut yang dapat diterapkan oleh pemilik data.');
ul(tujuanPoin);

sub('Manfaat Penelitian');
ul([
	'Manfaat teoretis: memperkaya kajian penerapan statistik deskriptif, korelasi, dan pemodelan klasifikasi pada data tabular.',
	'Manfaat praktis: memberikan gambaran cepat kondisi data dan prioritas pembersihan sebelum data dianalisis lebih lanjut.',
	'Manfaat metodologis: menyediakan alur analisis yang terdokumentasi sehingga hasil dapat diulang dan diverifikasi.',
]);

sub('Batasan Masalah');
ul([
	`Ruang lingkup terbatas pada satu berkas data ("${fileName}", lembar "${sheet.name}") yang dianalisis secara otomatis tanpa intervensi manual.`,
	'Hasil bersifat deskriptif dan asosiatif sehingga tidak membuktikan hubungan sebab-akibat.',
	'Deteksi tipe kolom, kolom persediaan, dan atribut target dilakukan otomatis dan perlu diverifikasi oleh pemilik data.',
	'Deteksi pencilan memakai aturan IQR yang kurang tepat pada sebaran sangat miring.',
]);
